// VHS-Band: Chroma-Versatz, zeilenweises Zittern, wanderndes Stoerband,
// Rauschen — der Beat verstaerkt den Glitch kurz.
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
vec4 farbe(vec2 uv, vec4 src)
{
    float zeit = uTime;
    float glitch = 0.3 + 0.7 * beat;
    float zeile = floor(uv.y * uResolution.y);
    float wackel = (hash(vec2(zeile, floor(zeit * 12.0))) - 0.5) * 0.004 * glitch;
    float band = smoothstep(0.02, 0.0, abs(fract(uv.y + zeit * 0.08) - 0.5) - 0.015);
    wackel += band * 0.01 * glitch;
    vec2 quelle = vec2(uv.x + wackel, uv.y);
    float versatz = 0.0022 + 0.003 * glitch * band;
    vec3 farbe;
    farbe.r = texture(uTex, quelle + vec2(versatz, 0.0)).r;
    farbe.g = texture(uTex, quelle).g;
    farbe.b = texture(uTex, quelle - vec2(versatz, 0.0)).b;
    float grau = dot(farbe, vec3(0.299, 0.587, 0.114));
    farbe = mix(vec3(grau), farbe, 0.8);                 // leicht entsaettigt
    float rauschen = hash(vec2(zeile, floor(zeit * 60.0)) + uv.x * 7.0);
    farbe += (rauschen - 0.5) * (0.06 + 0.12 * band);
    farbe *= 0.94 + 0.06 * sin(uv.y * uResolution.y * 3.14159);
    return vec4(farbe, 1.0);
}
